package com.interview.tier2;
public class ReverseLinkedList {static class Node{int data;Node next;Node(int d){data=d;}}public static Node iterative(Node h){Node p=null,c=h;while(c!=null){Node n=c.next;c.next=p;p=c;c=n;}return p;}public static Node recursive(Node h){if(h==null||h.next==null)return h;Node n=recursive(h.next);h.next.next=h;h.next=null;return n;}static void print(Node h){while(h!=null){System.out.print(h.data+" ");h=h.next;}System.out.println();}public static void main(String[] args){Node h=new Node(1);h.next=new Node(2);h.next.next=new Node(3);print(h);h=iterative(h);print(h);h=recursive(h);print(h);}}
